#include <stdio.h>

int say(int n) {
    int c = 0;
    for (int i = 1; i <= n; i *= 2)
        for (int j = 0; j < n; j++)
            c++;
    return c;
}

int main(void) {
    printf("%d\n", say(8));
    printf("%d\n", say(16));
    return 0;
}

