#include <stdio.h>
#include <stdlib.h>

typedef struct Dugum {
    int veri;
    struct Dugum *onceki, *sonraki;
} Dugum;

int sonaEkle(Dugum **bas, Dugum **kuyruk, int v) {
    Dugum *yeni = malloc(sizeof(*yeni));
    if (yeni == NULL) return 0;
    yeni->veri = v;
    yeni->sonraki = NULL;
    yeni->onceki = *kuyruk;
    if (*kuyruk != NULL) (*kuyruk)->sonraki = yeni;
    else                 *bas = yeni;
    *kuyruk = yeni;
    return 1;
}

int main(void) {
    Dugum *bas = NULL, *kuyruk = NULL;
    for (int i = 1; i <= 4; i++) sonaEkle(&bas, &kuyruk, i * 10);

    for (Dugum *p = bas; p != NULL; p = p->sonraki)
        printf("%d%s", p->veri, p->sonraki ? " " : "\n");

    for (Dugum *p = kuyruk; p != NULL; p = p->onceki)
        printf("%d%s", p->veri, p->onceki ? " " : "\n");

    while (bas != NULL) { Dugum *t = bas; bas = bas->sonraki; free(t); }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Dugum {
    int veri;
    struct Dugum *onceki, *sonraki;
} Dugum;

void sil(Dugum **bas, Dugum *p) {
    if (p->onceki != NULL) p->onceki->sonraki = p->sonraki;
    else                   *bas = p->sonraki;
    if (p->sonraki != NULL) p->sonraki->onceki = p->onceki;
    free(p);
}

int main(void) {
    Dugum *d[4];
    for (int i = 0; i < 4; i++) {
        d[i] = malloc(sizeof(Dugum));
        if (d[i] == NULL) return 1;
        d[i]->veri = (i + 1) * 10;
        d[i]->onceki = (i == 0) ? NULL : d[i - 1];
        d[i]->sonraki = NULL;
        if (i > 0) d[i - 1]->sonraki = d[i];
    }
    Dugum *bas = d[0];

    sil(&bas, d[1]);
    for (Dugum *p = bas; p; p = p->sonraki)
        printf("%d%s", p->veri, p->sonraki ? " " : "\n");

    sil(&bas, bas);
    for (Dugum *p = bas; p; p = p->sonraki)
        printf("%d%s", p->veri, p->sonraki ? " " : "\n");

    while (bas) { Dugum *t = bas; bas = bas->sonraki; free(t); }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Dugum {
    int veri;
    struct Dugum *sonraki;
} Dugum;

/* kuyruk isaretcisi tutar: kuyruk->sonraki bastir */
Dugum *sonaEkle(Dugum *kuyruk, int v) {
    Dugum *yeni = malloc(sizeof(*yeni));
    if (yeni == NULL) return kuyruk;
    yeni->veri = v;
    if (kuyruk == NULL) { yeni->sonraki = yeni; return yeni; }
    yeni->sonraki = kuyruk->sonraki;
    kuyruk->sonraki = yeni;
    return yeni;
}

int main(void) {
    Dugum *kuyruk = NULL;
    for (int i = 1; i <= 5; i++) kuyruk = sonaEkle(kuyruk, i);

    printf("%d %d\n", kuyruk->sonraki->veri, kuyruk->veri);

    int sayi = 0;
    Dugum *p = kuyruk->sonraki;
    do { sayi++; p = p->sonraki; } while (p != kuyruk->sonraki);
    printf("%d\n", sayi);

    p = kuyruk->sonraki;
    for (int i = 0; i < 7; i++) { printf("%d", p->veri); p = p->sonraki; }
    printf("\n");

    Dugum *bas = kuyruk->sonraki;
    kuyruk->sonraki = NULL;
    while (bas) { Dugum *t = bas; bas = bas->sonraki; free(t); }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct { int *veri; int boyut, kapasite; } Vektor;

int ekle(Vektor *v, int x) {
    if (v->boyut == v->kapasite) {
        int yeniKap = (v->kapasite == 0) ? 2 : v->kapasite * 2;
        int *yeni = realloc(v->veri, (size_t)yeniKap * sizeof(int));
        if (yeni == NULL) return 0;
        v->veri = yeni;
        v->kapasite = yeniKap;
        printf("buyudu: %d\n", v->kapasite);
    }
    v->veri[v->boyut++] = x;
    return 1;
}

int main(void) {
    Vektor v = { NULL, 0, 0 };
    for (int i = 1; i <= 5; i++) ekle(&v, i);
    printf("%d %d %d\n", v.boyut, v.kapasite, v.veri[4]);
    free(v.veri);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Dugum {
    int veri;
    struct Dugum *sonraki;
} Dugum;

/* p dugumunden SONRAya ekler; baslik sayesinde bos liste ozel durum degil */
int ekleSonra(Dugum *p, int v) {
    Dugum *yeni = malloc(sizeof(*yeni));
    if (yeni == NULL) return 0;
    yeni->veri = v;
    yeni->sonraki = p->sonraki;
    p->sonraki = yeni;
    return 1;
}

/* p'den SONRAKI dugumu siler */
void silSonra(Dugum *p) {
    Dugum *hedef = p->sonraki;
    if (hedef == NULL) return;
    p->sonraki = hedef->sonraki;
    free(hedef);
}

int main(void) {
    Dugum baslik;
    baslik.veri = -1;
    baslik.sonraki = NULL;

    ekleSonra(&baslik, 30);
    ekleSonra(&baslik, 20);
    ekleSonra(&baslik, 10);

    for (Dugum *p = baslik.sonraki; p; p = p->sonraki)
        printf("%d%s", p->veri, p->sonraki ? " " : "\n");

    silSonra(&baslik);
    silSonra(baslik.sonraki);

    for (Dugum *p = baslik.sonraki; p; p = p->sonraki)
        printf("%d%s", p->veri, p->sonraki ? " " : "\n");

    Dugum *p = baslik.sonraki;
    while (p) { Dugum *t = p; p = p->sonraki; free(t); }
    return 0;
}

topics.notes:
## Yığın neden bu kadar çok yerde karşımıza çıkıyor?

Yığın (stack) LIFO disiplinidir: son giren ilk çıkar. Bu kadar basit bir kural, "en son açılanı
ilk kapat" yapısındaki her problemi çözer: parantezler, HTML etiketleri, fonksiyon çağrıları,
geri al (undo), geri izleme (backtracking), ifade değerlendirme.

| İşlem | Dizi tabanlı | Bağlı liste tabanlı |
|---|---|---|
| `push` | $O(1)$ (dinamikse amortize $O(1)$) | $O(1)$ |
| `pop` | $O(1)$ | $O(1)$ |
| `peek` | $O(1)$ | $O(1)$ |
| `bosMu` | $O(1)$ | $O(1)$ |
| Bellek | bitişik, kapasite sınırı var | düğüm başına +8 bayt, sınırsız |

Yığının **tüm** işlemleri en kötü durumda da $O(1)$'dir (dizi büyütme hariç). Bu yüzden yığın
tabanlı çözümler hızlıdır.

## Parantez denetimi

Kural: açan parantez gelirse yığına koy; kapanan gelirse yığının tepesi onun eşi olmalı.

```c
int dengeliMi(const char *s) {
    char y[256];
    int t = 0;                                  /* tepe = bir sonraki bos yer */
    for (int i = 0; s[i] != '\0'; i++) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            if (t == 256) return 0;
            y[t++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (t == 0) return 0;               /* fazla kapanis */
            char a = y[--t];
            if ((c == ')' && a != '(') ||
                (c == ']' && a != '[') ||
                (c == '}' && a != '{')) return 0;
        }
    }
    return t == 0;                              /* kapanmamis acilis kaldi mi? */
}
```

İki tuzak: (1) yığın boşken kapanış gelmesi, (2) döngü bitince yığında eleman kalması. Sadece
sayaçla (açılan sayısı = kapanan sayısı) çözülmez; `([)]` sayıları eşit ama geçersizdir.

## Infix'ten postfix'e (Shunting-yard)

Postfix (sonek) gösterimde parantez yoktur, değerlendirme tek geçişte yığınla yapılır. Dönüşüm
algoritması:

1. **Operand** ise doğrudan çıktıya yaz.
2. **Operatör** ise: yığının tepesindeki operatörün önceliği bundan **büyük veya eşit** olduğu
   sürece (sol birleşmeli operatörler için) tepeyi çıktıya al; sonra bunu yığına koy.
3. `(` geldiyse yığına koy. `)` geldiyse `(` görene kadar yığından çıktıya aktar, `(`'yi at.
4. Girdi bitince yığında kalanları çıktıya boşalt.

Öncelik: `^` (3, sağ birleşmeli) > `*`, `/` (2) > `+`, `-` (1).

**Örnek: `A+B*C-D`**

| Sembol | Yığın | Çıktı |
|---|---|---|
| A | | A |
| + | + | A |
| B | + | AB |
| * | +* | AB |
| C | +* | ABC |
| - | - | ABC*+ |
| D | - | ABC*+D |
| son | | ABC*+D- |

Sonuç: `ABC*+D-`. İkinci örnek: `(A+B)*(C-D)` $\rightarrow$ `AB+CD-*`.

## Postfix değerlendirme

```c
/* "53+82-*" gibi tek basamakli postfix ifadeyi hesaplar */
int postfixDegerle(const char *s) {
    int y[64], t = 0;
    for (int i = 0; s[i]; i++) {
        if (s[i] >= '0' && s[i] <= '9') {
            y[t++] = s[i] - '0';
        } else {
            int b = y[--t], a = y[--t];          /* SIRA onemli: ust olan sagdaki */
            switch (s[i]) {
                case '+': y[t++] = a + b; break;
                case '-': y[t++] = a - b; break;
                case '*': y[t++] = a * b; break;
                case '/': y[t++] = a / b; break;
            }
        }
    }
    return y[0];
}
```

`53+82-*` için: 5,3 yığında $\rightarrow$ `+` $\rightarrow$ 8; 8,2 $\rightarrow$ `-` $\rightarrow$ 6;
sonra `*` $\rightarrow$ 48. Çıkarma ve bölmede **ilk çıkan ikinci operanddır**; `a - b` yerine
`b - a` yazmak klasik hatadır.

## Geri izleme (backtracking) ve yığın

Labirentten çıkış, $n$-vezir, küme alt kümeleri: hepsi "bir adım at, tıkanırsan son adımı geri
al" der. Özyinelemeli yazarsanız yığını derleyici tutar (çağrı yığını); döngüyle yazarsanız
yığını siz tutarsınız. Özyinelemeli her çözüm açık yığınla döngüye çevrilebilir — 5. haftanın
konusu budur.

> [!dikkat]
> `pop` öncesi **her zaman** boşluk denetimi yapın. Dizi tabanlı yığında `y[--t]` ifadesi `t == 0`
> iken `y[-1]`'e yazar; bu tanımsız davranıştır ve sınavda "hatayı bul" sorusunun cevabıdır.

> [!sınav]
> En sık çıkan üç soru: bir infix ifadeyi postfix'e çevirme (adım tablosuyla), bir postfix
> ifadenin değeri, ve verilen push/pop dizisinin sonunda yığının içeriği.

