#include <stdio.h>

int postfixDegerle(const char *s) {
    int y[32], t = 0;
    for (int i = 0; s[i] != '\0'; i++) {
        if (s[i] >= '0' && s[i] <= '9') {
            y[t++] = s[i] - '0';
        } else {
            int b = y[--t];
            int a = y[--t];
            switch (s[i]) {
                case '+': y[t++] = a + b; break;
                case '-': y[t++] = a - b; break;
                case '*': y[t++] = a * b; break;
                case '/': y[t++] = a / b; break;
            }
        }
    }
    return y[0];
}

int main(void) {
    printf("%d\n", postfixDegerle("53+82-*"));
    printf("%d\n", postfixDegerle("92-3*"));
    printf("%d\n", postfixDegerle("234*+"));
    return 0;
}

#include <stdio.h>

static int oncelik(char o) {
    if (o == '+' || o == '-') return 1;
    if (o == '*' || o == '/') return 2;
    return 0;
}

void infixToPostfix(const char *s, char *cikti) {
    char y[64];
    int t = 0, k = 0;
    for (int i = 0; s[i] != '\0'; i++) {
        char c = s[i];
        if (c >= 'A' && c <= 'Z') {
            cikti[k++] = c;
        } else if (c == '(') {
            y[t++] = c;
        } else if (c == ')') {
            while (t > 0 && y[t - 1] != '(') cikti[k++] = y[--t];
            if (t > 0) t--;                      /* '(' atilir */
        } else {
            while (t > 0 && oncelik(y[t - 1]) >= oncelik(c))
                cikti[k++] = y[--t];
            y[t++] = c;
        }
    }
    while (t > 0) cikti[k++] = y[--t];
    cikti[k] = '\0';
}

int main(void) {
    char c[64];
    infixToPostfix("A+B*C-D", c);      printf("%s\n", c);
    infixToPostfix("(A+B)*(C-D)", c);  printf("%s\n", c);
    infixToPostfix("A*B+C*D", c);      printf("%s\n", c);
    return 0;
}

#include <stdio.h>

#define KAP 10
static int y[KAP];
static int t = 0;                 /* tepe: bir sonraki bos yer */

static int ekle(int v) { if (t == KAP) return 0; y[t++] = v; return 1; }
static int cikar(int *v) { if (t == 0) return 0; *v = y[--t]; return 1; }

int main(void) {
    int v;
    ekle(1); ekle(2); ekle(3);
    cikar(&v); printf("%d ", v);
    ekle(4); ekle(5);
    cikar(&v); printf("%d ", v);
    cikar(&v); printf("%d\n", v);

    printf("tepe=%d\n", t);
    while (cikar(&v)) printf("%d", v);
    printf("\n");
    printf("%d %d\n", cikar(&v), t);
    return 0;
}

#include <stdio.h>

/* 1, 2, 3 sayilarindan toplami 4 olan alt kumeleri acik yiginla arar */
int main(void) {
    int secim[3];          /* secim[k]: k+1 sayisi alindi mi */
    int i = 0, bulunan = 0;
    secim[0] = -1;

    while (i >= 0) {
