            if (i == 2) {                /* son seviye: cozumu degerlendir */
                int toplam = 0;
                for (int k = 0; k < 3; k++)
                    if (secim[k] == 1) toplam += k + 1;
                if (toplam == 4) {
                    bulunan++;
                    for (int k = 0; k < 3; k++)
                        if (secim[k] == 1) printf("%d", k + 1);
                    printf("\n");
                }
            } else {
                i++;
                secim[i] = -1;           /* yeni seviyeyi sifirla */
            }
        } else {
            i--;                         /* geri izleme */
        }
    }
    printf("bulunan=%d\n", bulunan);
