#define KAP 5
typedef struct { int veri[KAP]; int on, arka, sayi; } Kuyruk;

static void baslat(Kuyruk *k) { k->on = 0; k->arka = -1; k->sayi = 0; }

static int ekle(Kuyruk *k, int v) {
    if (k->sayi == KAP) return 0;
    k->arka = (k->arka + 1) % KAP;
    k->veri[k->arka] = v;
    k->sayi++;
    return 1;
}

static int cikar(Kuyruk *k, int *v) {
    if (k->sayi == 0) return 0;
    *v = k->veri[k->on];
    k->on = (k->on + 1) % KAP;
    k->sayi--;
    return 1;
}

int main(void) {
    Kuyruk k;
    int v;
    baslat(&k);
    for (int i = 1; i <= 4; i++) ekle(&k, i * 10);

    cikar(&k, &v); printf("%d ", v);
    cikar(&k, &v); printf("%d\n", v);

    ekle(&k, 50); ekle(&k, 60); ekle(&k, 70);
    printf("on=%d arka=%d sayi=%d\n", k.on, k.arka, k.sayi);
    printf("%d\n", ekle(&k, 80));

    while (cikar(&k, &v)) printf("%d%s", v, k.sayi ? " " : "\n");
    return 0;
}

