#include <stdio.h>

#define KAP 6
typedef struct { int v[KAP]; int on, sayi; } Deque;

static void baslat(Deque *d) { d->on = 0; d->sayi = 0; }

static int oneEkle(Deque *d, int x) {
    if (d->sayi == KAP) return 0;
    d->on = (d->on - 1 + KAP) % KAP;       /* negatif mod tuzagina dikkat */
    d->v[d->on] = x;
    d->sayi++;
    return 1;
}

static int arkayaEkle(Deque *d, int x) {
    if (d->sayi == KAP) return 0;
    d->v[(d->on + d->sayi) % KAP] = x;
    d->sayi++;
    return 1;
}

static int ondenCikar(Deque *d, int *x) {
    if (d->sayi == 0) return 0;
    *x = d->v[d->on];
    d->on = (d->on + 1) % KAP;
    d->sayi--;
    return 1;
}

static int arkadanCikar(Deque *d, int *x) {
    if (d->sayi == 0) return 0;
    *x = d->v[(d->on + d->sayi - 1) % KAP];
    d->sayi--;
    return 1;
}

static void yaz(const Deque *d) {
    for (int i = 0; i < d->sayi; i++)
        printf("%d%s", d->v[(d->on + i) % KAP], i + 1 == d->sayi ? "\n" : " ");
}

int main(void) {
    Deque d;
    int x;
    baslat(&d);

    arkayaEkle(&d, 1);
    arkayaEkle(&d, 2);
    oneEkle(&d, 0);
    oneEkle(&d, -1);
    yaz(&d);

    ondenCikar(&d, &x);   printf("%d ", x);
    arkadanCikar(&d, &x); printf("%d\n", x);
    printf("on=%d sayi=%d\n", d.on, d.sayi);
    yaz(&d);
    return 0;
}

