    if (k->sol == NULL && k->sag == NULL) return k->sembol - '0';
    int a = degerle(k->sol);
    int b = degerle(k->sag);
    switch (k->sembol) {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
    }
    return 0;
}

