    Dugum *t = yeni('*',
                    yeni('+', yeni('2', NULL, NULL), yeni('3', NULL, NULL)),
                    yeni('-', yeni('9', NULL, NULL), yeni('5', NULL, NULL)));

    inorderYaz(t);    printf("\n");
    postorderYaz(t);  printf("\n");
    printf("%d\n", degerle(t));
    yok(t);
