    y->anahtar = k;
    y->sonraki = tablo[i];      /* basa ekleme: O(1) */
    tablo[i] = y;
}

static int uzunluk(int i) {
    int c = 0;
    for (Dugum *p = tablo[i]; p != NULL; p = p->sonraki) c++;
    return c;
}

int main(void) {
    int d[] = { 10, 22, 31, 4, 15, 28, 17, 88, 59 };
    for (int i = 0; i < 9; i++) ekle(d[i]);

    for (int i = 0; i < M; i++) printf("%d", uzunluk(i));
    printf("\n");

    for (Dugum *p = tablo[3]; p != NULL; p = p->sonraki)
        printf("%d%s", p->anahtar, p->sonraki ? " " : "\n");

    for (int i = 0; i < M; i++) {
        Dugum *p = tablo[i];
        while (p) { Dugum *t = p; p = p->sonraki; free(t); }
        tablo[i] = NULL;
    }
    return 0;
}

#include <stdio.h>

#define M 13
#define BOS     -1
#define SILINDI -2

static int T[M];

static void baslat(void) { for (int i = 0; i < M; i++) T[i] = BOS; }

static int ekle(int k) {
    int h = k % M;
    for (int i = 0; i < M; i++) {
        int j = (h + i) % M;
        if (T[j] == BOS || T[j] == SILINDI) { T[j] = k; return j; }
        if (T[j] == k) return j;
    }
    return -1;
}

static int ara(int k) {
    int h = k % M;
    for (int i = 0; i < M; i++) {
        int j = (h + i) % M;
        if (T[j] == BOS) return -1;     /* BOS'ta dur */
        if (T[j] == k) return j;        /* SILINDI ise atla, devam et */
    }
    return -1;
}

static int sil(int k) {
    int j = ara(k);
    if (j < 0) return 0;
    T[j] = SILINDI;
    return 1;
}

int main(void) {
    baslat();
    printf("%d", ekle(5));
    printf("%d", ekle(18));
    printf("%d\n", ekle(31));

    printf("%d %d\n", ara(31), ara(44));
    printf("%d\n", sil(18));
    printf("%d %d\n", T[6], ara(31));

    T[6] = BOS;                         /* mezar tasi yerine BOS yazilsaydi */
    printf("%d\n", ara(31));
    return 0;
}

#include <stdio.h>

#define M 11
#define BOS -1

static int T[M];

/* h1(k) = k % M,  h2(k) = 1 + (k % (M-1))  -> asla 0 olmaz */
static int ekle(int k) {
    int h1 = k % M, h2 = 1 + (k % (M - 1));
    for (int i = 0; i < M; i++) {
        int j = (h1 + i * h2) % M;
        if (T[j] == BOS) { T[j] = k; return i + 1; }
    }
    return 0;
}

int main(void) {
    for (int i = 0; i < M; i++) T[i] = BOS;

    int d[] = { 10, 22, 31, 4, 15, 28, 17 };
    for (int i = 0; i < 7; i++)
        printf("%d:%d ", d[i], ekle(d[i]));
    printf("\n");

    for (int i = 0; i < M; i++)
        if (T[i] != BOS) printf("%d:%d ", i, T[i]);
    printf("\n");
    return 0;
}

topics.notes:
## Üç hızlı sıralama, üç farklı takas

Geçen dönem eklemeli, seçmeli ve baloncuk sıralamayı gördünüz: üçü de $\Theta(n^2)$. Bu hafta
$\Theta(n \log n)$ ligine çıkıyoruz. Karşılaştırmaya dayalı sıralamanın **alt sınırı**
$\Omega(n \log n)$'dir (karar ağacı argümanı: $n!$ olası dizilim, ağacın yüksekliği en az
$\log_2(n!) \approx n\log_2 n - 1{,}44n$), yani bu üç algoritma teorik sınırda çalışır.

## Birleştirmeli sıralama (merge sort)

Böl-yönet: diziyi ortadan ikiye böl, iki yarıyı sırala, **birleştir**.

```c
static void birlestir(int a[], int lo, int orta, int hi, int *yardim) {
    int i = lo, j = orta + 1, k = lo;
    while (i <= orta && j <= hi)
        yardim[k++] = (a[i] <= a[j]) ? a[i++] : a[j++];   /* <= : KARARLILIK burada */
    while (i <= orta) yardim[k++] = a[i++];
    while (j <= hi)   yardim[k++] = a[j++];
    for (int t = lo; t <= hi; t++) a[t] = yardim[t];
}

void mergeSort(int a[], int lo, int hi, int *yardim) {
    if (lo >= hi) return;
    int orta = lo + (hi - lo) / 2;
    mergeSort(a, lo, orta, yardim);
    mergeSort(a, orta + 1, hi, yardim);
    birlestir(a, lo, orta, hi, yardim);
}
```

Bağıntı $T(n) = 2T(n/2) + \Theta(n) \Rightarrow \Theta(n \log n)$ — **her durumda**, girdiye bakmaz.
Bedeli $\Theta(n)$ yardımcı bellektir. `a[i] <= a[j]` karşılaştırmasındaki **eşitlik** kritiktir:
eşit anahtarlarda sol yarı (daha eski kayıt) önce alındığı için merge sort **kararlıdır**; `<`
yazarsanız kararlılığı kaybedersiniz.

## Hızlı sıralama (quicksort)

Böl-yönet'in diğer yüzü: önce **bölümle** (partition), sonra yönet; birleştirme adımı yok.

```c
/* Lomuto bolumleme: son eleman pivot, <= pivot olanlar sola toplanir */
static int bolumle(int a[], int lo, int hi) {
    int pivot = a[hi], i = lo - 1;
    for (int j = lo; j < hi; j++) {
        if (a[j] <= pivot) {
            i++;
            int t = a[i]; a[i] = a[j]; a[j] = t;
        }
    }
    i++;
    int t = a[i]; a[i] = a[hi]; a[hi] = t;
    return i;                       /* pivotun NIHAI yeri */
}

void quickSort(int a[], int lo, int hi) {
    if (lo >= hi) return;
    int p = bolumle(a, lo, hi);
    quickSort(a, lo, p - 1);
    quickSort(a, p + 1, hi);
}
```

Bölümlemeden sonra pivot **kesin yerindedir**; bir daha dokunulmaz. Ortalama durumda bölme
dengelidir ve $T(n) = 2T(n/2) + \Theta(n) \Rightarrow \Theta(n \log n)$.

### En kötü durum: sıralı dizi

Pivot her seferinde en küçük veya en büyük eleman çıkarsa bölme $(0, n-1)$ olur:

$$T(n) = T(n-1) + \Theta(n) \Rightarrow \Theta(n^2)$$

Son elemanı pivot alan bu gerçekleştirim için en kötü girdi **zaten sıralı** (veya ters sıralı)
dizidir — BST'nin dejenerasyonuyla aynı hikâye. Üstelik özyineleme derinliği $n$ olduğu için
yığın da taşabilir. Çözümler:

| Önlem | Etkisi |
|---|---|
| Rastgele pivot | En kötü durumu tesadüfe bağlar; beklenen süre $\Theta(n \log n)$ |
| Üçün ortası (median-of-three) | İlk/orta/son elemanın ortancası pivot olur; sıralı girdiyi kurtarır |
| Küçük parçalarda eklemeli sıralama | $n < 10$ için ek yük azalır (gerçek kütüphane hilesi) |
| Önce küçük parçayı özyinele | Yığın derinliğini $O(\log n)$'e sabitler |

## Karşılaştırma tablosu — sınavda doğrudan sorulur

| Algoritma | En iyi | Ortalama | **En kötü** | Ek bellek | Kararlı | Yerinde |
|---|---|---|---|---|---|---|
| Eklemeli | $\Theta(n)$ | $\Theta(n^2)$ | $\Theta(n^2)$ | $O(1)$ | **Evet** | Evet |
| Seçmeli | $\Theta(n^2)$ | $\Theta(n^2)$ | $\Theta(n^2)$ | $O(1)$ | Hayır | Evet |
| Baloncuk | $\Theta(n)$ | $\Theta(n^2)$ | $\Theta(n^2)$ | $O(1)$ | **Evet** | Evet |
| **Merge sort** | $\Theta(n \log n)$ | $\Theta(n \log n)$ | $\Theta(n \log n)$ | $\Theta(n)$ | **Evet** | Hayır |
| **Quicksort** | $\Theta(n \log n)$ | $\Theta(n \log n)$ | $\Theta(n^2)$ | $O(\log n)$ | Hayır | Evet |
| **Heapsort** | $\Theta(n \log n)$ | $\Theta(n \log n)$ | $\Theta(n \log n)$ | $O(1)$ | Hayır | Evet |

**Kararlılık** (stability): eşit anahtarlı kayıtların göreli sırasının korunmasıdır. Neden önemli?
Önce bölüme, sonra nota göre sıralamak istiyorsanız, ikinci sıralama kararlı olmalıdır ki birinci
sıralamanın sonucu bozulmasın. Uzak takas yapan algoritmalar (seçmeli, quicksort, heapsort)
kararlılığı doğal olarak kaybeder.

> [!ipucu]
> Pratikte hangisi kullanılır? C'nin `qsort`u ve C++'ın `std::sort`u quicksort tabanlı melez
> (introsort: derinlik sınırı aşılırsa heapsort'a geçer, küçük parçalarda eklemeli sıralama) —
> böylece ortalamada quicksort hızı, en kötü durumda $n\log n$ garantisi elde edilir. Java'nın
> nesne sıralaması ise kararlılık gerektiği için merge sort türevi (TimSort) kullanır.

> [!sınav]
> Klasikler: verilen diziye Lomuto bölümlemesi uygulanınca ilk geçiş sonrası dizi; merge sort'un
> birleştirme adımlarının sırası; hangi algoritmanın kararlı/yerinde olduğu; quicksort'un en kötü
> durumunun hangi girdide oluştuğu.

